/* Relaywise product page. Tokens and the signature are recorded in DESIGN.md. */

:root {
  color-scheme: light;

  --bg: oklch(0.975 0.005 250);
  --surface: oklch(1 0 0);
  --tint: oklch(0.93 0.012 262);       /* chips, rule specimens */
  --footer: oklch(0.955 0.008 262);
  --line: oklch(0.88 0.01 262);        /* decorative separators only */
  --ink: oklch(0.23 0.035 262);
  --muted: oklch(0.46 0.025 262);
  --accent: oklch(0.87 0.165 95);      /* signal yellow, always with ink text or on ink */
  --accent-hover: oklch(0.82 0.17 90);
  --ring: oklch(0.5 0.2 262);
  --board-text: oklch(0.96 0.005 262);
  --board-muted: oklch(0.78 0.02 262);
  --board-line: oklch(0.36 0.03 262);

  --font: "Archivo", system-ui, -apple-system, "Segoe UI", sans-serif;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);   /* ease-out quint */

  --z-skip: 10;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
}

h1, h2, h3 { margin: 0; text-wrap: balance; }
p, ul, ol, figure { margin: 0; }
ul, ol { padding: 0; list-style: none; }

::selection { background: var(--accent); color: var(--ink); }

a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.wrap {
  width: min(100% - 2.5rem, 76rem);
  margin-inline: auto;
}

.vh {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -5rem;
  z-index: var(--z-skip);
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--surface);
  font-weight: 700;
  text-decoration: none;
  border-radius: 0.5rem;
}
.skip:focus { top: 1rem; }

/* ---------- Signature: the route line (origin ring, rule, arrowhead) ---------- */

.route {
  display: inline-flex;
  align-items: center;
  flex: 1 1 auto;
  min-width: 2rem;
}
.route::before {
  content: "";
  flex: none;
  width: 0.6rem;
  height: 0.6rem;
  border: 2px solid currentColor;
  border-radius: 50%;
}
.route i {
  flex: 1;
  min-width: 0.5rem;
  height: 2px;
  background: currentColor;
}
.route::after {
  content: "";
  flex: none;
  border-left: 0.5rem solid currentColor;
  border-block: 0.32rem solid transparent;
}

/* Forward actions carry a short route that stretches toward its target on hover/focus.
   Fixed box so the control never changes size; only transforms move. */
.route--go {
  flex: none;
  width: 2.25rem;
  min-width: 0;
  margin-left: 0.5rem;
}
.route--go i {
  transform: scaleX(0.45);
  transform-origin: left center;
  transition: transform 200ms var(--ease);
}
.route--go::after {
  transform: translateX(-0.63rem);   /* 0.55 of the 1.15rem rule */
  transition: transform 200ms var(--ease);
}
a:focus-visible .route--go i { transform: scaleX(1); }
a:focus-visible .route--go::after { transform: translateX(0); }
@media (hover: hover) {
  a:hover .route--go i { transform: scaleX(1); }
  a:hover .route--go::after { transform: translateX(0); }
}

.route--mark { flex: none; width: 1.6rem; min-width: 0; }

/* ---------- Buttons & links ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: 0 1.25rem;
  border: 2px solid var(--ink);
  border-radius: 0.5rem;
  color: var(--ink);
  font-weight: 700;
  font-stretch: 105%;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 150ms var(--ease);
}
.btn--primary { background: var(--accent); }
.btn--secondary { background: var(--surface); }
.btn--small { min-height: 2.75rem; padding: 0 1rem; font-size: 0.9375rem; }
.btn:active { transform: translateY(1px); }
@media (hover: hover) {
  .btn--primary:hover { background: var(--accent-hover); }
  .btn--secondary:hover { background: var(--tint); }
}

.text-link,
.more {
  font-weight: 600;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.25em;
}
@media (hover: hover) {
  .text-link:hover,
  .more:hover { text-decoration-thickness: 2px; }
}

/* ---------- Header ---------- */

.site-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1.5rem;
  padding-block: 1.25rem;
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  font-size: 1.25rem;
  font-weight: 800;
  font-stretch: 125%;
  letter-spacing: -0.01em;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
}
.site-nav > a:not(.btn) {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 600;
  text-decoration: none;
}
@media (hover: hover) {
  .site-nav > a:not(.btn):hover { text-decoration: underline; text-underline-offset: 0.25em; }
}
/* ponytail: on small screens the in-page anchors go; the hero's "See pricing" link and scrolling cover them. */
@media (max-width: 40rem) {
  .nav-anchor { display: none; }
}

/* ---------- Hero ---------- */

.hero {
  display: grid;
  gap: 3rem;
  padding-block: 3.5rem 2rem;
}
@media (min-width: 60rem) {
  .hero {
    grid-template-columns: 1.05fr 1fr;
    align-items: center;
    gap: 4rem;
    padding-block: 5rem 3rem;
  }
}

.hero h1 {
  font-size: clamp(2.4rem, 1.2rem + 4.2vw, 4.75rem);
  font-weight: 800;
  font-stretch: 125%;
  line-height: 1.02;
  letter-spacing: -0.02em;
}

.lede {
  max-width: 34em;
  margin-top: 1.5rem;
  color: var(--muted);
  font-size: 1.1875rem;
  line-height: 1.55;
  text-wrap: pretty;
}

.cta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
}
.cta-row .btn { min-height: 3.5rem; padding-inline: 1.5rem; font-size: 1.0625rem; }

.fine { margin-top: 1rem; color: var(--muted); font-size: 0.9375rem; }

/* The sorting board: the one dark object on the page, where routes are drawn in yellow. */
.board {
  padding: 1.5rem;
  background: var(--ink);
  color: var(--board-text);
  border-radius: 1rem;
  box-shadow: 0 1.25rem 2.5rem -1.5rem oklch(0.23 0.035 262 / 0.55);
}
.board figcaption {
  color: var(--board-muted);
  font-size: 0.9375rem;
  line-height: 1.5;
  padding-bottom: 0.75rem;
}
.board-list li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(2.5rem, 5rem) auto;
  align-items: center;
  gap: 0.75rem;
  padding-block: 1rem;
  border-top: 1px solid var(--board-line);
  line-height: 1.7;
}
.board .route { color: var(--accent); }
.subject { font-weight: 500; overflow-wrap: anywhere; }
.owner {
  justify-self: start;
  padding: 0.15rem 0.7rem;
  background: var(--accent);
  color: var(--ink);
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 700;
  font-stretch: 105%;
  white-space: nowrap;
}
@media (max-width: 30rem) {
  .board { padding: 1.25rem 1rem; }
  .board-list li { grid-template-columns: minmax(2.5rem, 1fr) auto; row-gap: 0.4rem; }
  .subject { grid-column: 1 / -1; }
}

/* ---------- Section heads ---------- */

.features,
.pricing { padding-top: 6rem; }

.section-head { display: grid; gap: 1rem; margin-bottom: 2.5rem; }
.section-head h2 {
  max-width: 16ch;
  font-size: clamp(1.9rem, 1.3rem + 2vw, 3rem);
  font-weight: 800;
  font-stretch: 118%;
  line-height: 1.08;
  letter-spacing: -0.015em;
}
.section-head p { max-width: 42ch; color: var(--muted); font-size: 1.0625rem; }

/* Features: heading and intro side by side. Pricing keeps them stacked (varied rhythm). */
@media (min-width: 56rem) {
  .features .section-head { grid-template-columns: 1fr 1fr; align-items: end; gap: 3rem; }
}

/* ---------- Feature cards ---------- */

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr));
  gap: 1.25rem;
}

.card {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1.25rem 1.25rem 1.5rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.75rem;
}
.card h3 {
  margin-top: 0.75rem;
  font-size: 1.25rem;
  font-weight: 750;
  font-stretch: 112%;
  line-height: 1.2;
}
.card > p:not(.spec) { color: var(--muted); }

/* Rule specimen: each card's feature stated as a route. */
.spec {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.6rem;
  padding: 0.6rem 0.75rem;
  background: var(--tint);
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-stretch: 90%;
  font-weight: 500;
  line-height: 1.4;
}
.spec .route { min-width: 2.25rem; max-width: 4rem; }
.spec b { font-weight: 750; }

.chips { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.chips li {
  padding: 0.1rem 0.6rem;
  background: var(--tint);
  border-radius: 999px;
  font-size: 0.8125rem;
  font-weight: 600;
}
.chips .chip--beta { background: var(--accent); }

.more {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  min-height: 2.75rem;
  margin-top: auto;
}

/* ---------- Pricing ---------- */

.tiers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
  gap: 1.25rem;
  align-items: stretch;
}

.tier {
  display: flex;
  flex-direction: column;
  padding: 1.75rem;
  background: var(--surface);
  border: 1px solid var(--line);
