  --footer: oklch(0.955 0.008 262);
  --line: oklch(0.88 0.01 262);        /* decorative separators only */
  --ink: oklch(0.23 0.035 262);
  --muted: oklch(0.46 0.025 262);
  --accent: oklch(0.87 0.165 95);      /* signal yellow, always with ink text or on ink */
  --accent-hover: oklch(0.82 0.17 90);
