  --z-skip: 10;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
}

h1, h2, h3 { margin: 0; text-wrap: balance; }
p, ul, ol, figure { margin: 0; }
ul, ol { padding: 0; list-style: none; }

::selection { background: var(--accent); color: var(--ink); }

a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.wrap {
  width: min(100% - 2.5rem, 76rem);
  margin-inline: auto;
}

.vh {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -5rem;
  z-index: var(--z-skip);
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--surface);
  font-weight: 700;
  text-decoration: none;
  border-radius: 0.5rem;
}
.skip:focus { top: 1rem; }

/* ---------- Signature: the route line (origin ring, rule, arrowhead) ---------- */

.route {
  display: inline-flex;
  align-items: center;
  flex: 1 1 auto;
  min-width: 2rem;
}
.route::before {
  content: "";
  flex: none;
  width: 0.6rem;
  height: 0.6rem;
  border: 2px solid currentColor;
  border-radius: 50%;
}
.route i {
  flex: 1;
  min-width: 0.5rem;
  height: 2px;
  background: currentColor;
}
