  font-weight: 800;
  font-stretch: 125%;
  line-height: 1.02;
  letter-spacing: -0.02em;
}

.lede {
  max-width: 34em;
  margin-top: 1.5rem;
  color: var(--muted);
  font-size: 1.1875rem;
  line-height: 1.55;
  text-wrap: pretty;
}

.cta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
