.board {
  padding: 1.5rem;
  background: var(--ink);
  color: var(--board-text);
  border-radius: 1rem;
  box-shadow: 0 1.25rem 2.5rem -1.5rem oklch(0.23 0.035 262 / 0.55);
}
.board figcaption {
  color: var(--board-muted);
  font-size: 0.9375rem;
  line-height: 1.5;
  padding-bottom: 0.75rem;
}
.board-list li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(2.5rem, 5rem) auto;
  align-items: center;
  gap: 0.75rem;
  padding-block: 1rem;
  border-top: 1px solid var(--board-line);
  line-height: 1.7;
}
.board .route { color: var(--accent); }
.subject { font-weight: 500; overflow-wrap: anywhere; }
.owner {
  justify-self: start;
  padding: 0.15rem 0.7rem;
  background: var(--accent);
  color: var(--ink);
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 700;
  font-stretch: 105%;
  white-space: nowrap;
